examples.source:
let(
  fee = amount * bps / 10000,
  amount - fee
)

let(
  large = [price for price in prices if price >= minimum],
  {"total": sum(large), "count": len(large), "max": max(large)}
)

let(
  first = prices[0],
  rate = rates["adyen"],
  cents = total % 100,
  {"first": first, "rate": rate, "cents": cents}
)

let(
  delays = [base_delay * step for step in range(1, 4)],
  ready = all([delay <= ceiling for delay in delays]),
  switch(case ready => delays, else => [base_delay])
)

let(
  bin = slice(trim(card), 0, 6),
  brand = switch(
    case starts_with(bin, "4") => "visa",
    case starts_with(bin, "5") => "mastercard",
    else => "other"
  ),
  {bin: bin, brand: upper(brand), supported: contains(accepted, brand)}
)

let(
  parts = split(lower(reason), ";"),
  cleaned = [replace(part, "_", ":") for part in parts],
  {code: join(cleaned, "|"), urgent: ends_with(reason, "!")}
)

let(
  ranked = sort_by(channels, fees),
  best = channels[arg_min(fees)],
  {
    best: best,
    order: ranked,
    runner_up: ranked[1],
    place: rank(fees)[index_of(channels, best)],
    dearest: channels[arg_max(fees)],
    average: avg(fees),
    middle: median(fees)
  }
)

let(
  allowed = intersect(channels, whitelist),
  usable = except(allowed, blocked),
  ranked = sort_by_desc(channels, rates),
  {
    usable: usable,
    cheapest_two: bottom_k(channels, fees, 2),
    best_rate: first(top_k(channels, rates, 1)),
    by_rate: ranked,
    fees_desc: sort_desc(fees)
  }
)

let(
  recent = [sum(w) for w in windows(amounts, 3)],
  changes = deltas(amounts),
  batches = chunk(amounts, 2),
  {
    recent_totals: recent,
    biggest_jump: max(changes),
    batch_count: len(batches),
    first_batch: first(batches)
  }
)

let(
  by_channel = group_by(amounts, channels),
  running = cumsum(amounts),
  {
    totals: {k: sum(v) for k, v in by_channel},
    counts: {k: len(v) for k, v in by_channel},
    over_at: first([i for i in indices(amounts) if running[i] > limit])
  }
)

let(
  tail = percentile(latencies, 0.95),
  jitter = stddev(rates),
  backoff = [base_delay * pow(2, attempt) for attempt in range(3)],
  {
    p95: tail,
    jitter: jitter,
    degraded: tail > latency_limit || jitter > jitter_limit,
    backoff: backoff
  }
)

let(
  quote = fallback(
    route.fee_quote_v1(primary_status, primary_fee),
    route.fee_quote_v1(backup_status, backup_fee),
    ceiling_fee
  ),
  switch(
    case quote >= ceiling_fee => "ceiling",
    case quote > primary_fee  => "backup",
    else => "primary"
  )
)

let(
  region = switch(country,
    case "SG", "MY", "TH" => "asia",
    case "US", "CA"       => "na",
    else => "global"
  ),
  tier = switch(
    case amount >= 1000000 => "enterprise",
    case amount >= 10000   => "standard",
    else => "micro"
  ),
  region + ":" + tier
)

let(
  best = max(auth_rates),
  if(route.score_v1(best, cost) > 90.0, "adyen_primary", "stripe_backup")
)

let(
  healthy = [name for name, status in channel_statuses if route.is_healthy_v1(status)],
  live = len(healthy),
  switch(case live == 0 => [emergency_channel], else => healthy)
)

let(
  total = sum([weight for name, weight in weights]),
  [name for name, weight in weights if weight / total >= floor]
)

let(
  breached = any([score > ceiling for name, score in signals]),
  !trusted && (risk > 0.8 || breached || currency != settlement_currency) && enabled == true
)

let(
  scores = [model.fraud_v1(model.embed_v1(row)) for row in feature_rows],
  worst = max(scores),
  switch(
    case worst > 0.8 => "review",
    case worst > 0.5 => "challenge",
    else => "accept"
  )
)

let(
  amounts = [int(text) for text in amount_texts],
  [switch(
     case amount < 1000       => "micro",
     case amount <= 100000    => "standard",
     case amount >= 1000000   => "manual_review",
     else => "enhanced_review"
   ) for amount in amounts]
)

let(
  cents = [int(text) for text in amount_texts],
  total = sum(cents),
  captured = bool(captured_text),
  if(captured, "captured:" + string(float(total) / 100.0), "not_captured")
)

let(
  total_fee = sum(fees),
  {"gross_and_net": [gross, gross - total_fee], "fees": fees}
)

let(
  needs_review = order.amount > limit || order.currency != settlement,
  fee = order.amount * bps / 10000,
  {
    channel: switch(case needs_review => "manual", else => "auto"),
    net: order.amount - fee,
    reason: switch(
      case order.amount > limit          => "high_value",
      case order.currency != settlement  => "cross_border",
      else =>                                  "standard"
    )
  }
)

{
  cheapest: min_by(quotes, .fee).channel,
  surest: max_by(quotes, .success).channel,
  by_fee: [q.channel for q in sort_by(quotes, .fee)]
}

let(
  local = hour(paid_at, "Asia/Shanghai"),
  {
    night: local < 6 || local >= 22,
    weekend: weekday(paid_at, "Asia/Shanghai") >= 6,
    day: day(paid_at, "Asia/Shanghai"),
    month: month(paid_at, "Asia/Shanghai"),
    day_start: start_of_day(paid_at, "Asia/Shanghai"),
    settle_by: add_days(paid_at, 1, "Asia/Shanghai") + 2h,
    stale: now - paid_at > 30m,
    launched: paid_at >= time("2026-01-01T00:00:00+08:00")
  }
)

{
  visa: matches(card, "^4[0-9]{15}$"),
  masked: repeat("*", 12) + slice(card, 12, 16),
  channel: trim_prefix(trim_suffix(ref, ".sg"), "ch_"),
  batch: slice(order_no, 0, last_index_of(order_no, "-"))
}

let(
  running = [t <= cap for t in cumsum(amounts)],
  {within: take_while(amounts, running), beyond: drop_while(amounts, running)}
)

let(
  effective = merge(defaults, overrides),
  {
    sg: get(effective, "SG", 0),
    us: get(effective, "US", 0),
    unknown: get(effective, "ZZ", 0 - 1),
    configured: len(effective)
  }
)

let(
  fee = round(amount * 2.9%, @half_even) + money(30, currency(amount)),
  if(fee > cap, cap, fee)
)

let(
  m = money(order.minor, currency_of(order.code)),
  {amount: m, currency: currency(m), cents: minor(m), sign: sign(m)}
)

let(
  tier = switch(
    case volume >= USD 100000.00 => 1.8%,
    case volume >= USD 10000.00  => 2.2%,
    else => 2.9%),
  round(amount * tier, @half_even) + USD 0.20
)

let(
  costs = [round(amount * q.rate, @half_even) + q.fixed for q in quotes],
  {channel: quotes[arg_min(costs)].name, cost: min(costs)}
)

let(
  per_success = [round((amount * q.rate + q.fixed) / q.approval, @half_even) for q in quotes],
  quotes[arg_min(per_success)].name
)

let(
  quotes = {adyen: route.money_quote_v1("adyen", amount), stripe: route.money_quote_v1("stripe", amount)},
  if(quotes.adyen <= quotes.stripe, "adyen", "stripe")
)

let(
  processing = round(amount * 2.9%, @half_even) + money(30, currency(amount)),
  commission = round(amount * 8%, @half_even),
  {seller: amount - commission - processing, platform: commission, processor: processing}
)

let(
  fees = round(gross * 2.9%, @half_even) + money(30, currency(gross)) * count,
  using(market, round((gross - fees) -> USD, @half_even))
)

let(
  expected = using(market, round(paid -> EUR, @half_even)),
  deviation = settled / expected - 100%,
  deviation > 0.5% || deviation < -0.5%
)
